def _repository_contract_audit_builder(
    request: Mapping[str, Any],
) -> dict[str, Any]:
    constraints = request.get("constraints")
    constraints = dict(constraints) if isinstance(constraints, Mapping) else {}

    allowed = {"paths", "search_terms", "max_results"}
    unknown = sorted(set(constraints) - allowed)
    if unknown:
        raise SemanticCapabilityError(
            "SEMANTIC_CONSTRAINTS_UNSUPPORTED:" + ",".join(unknown)
        )

    raw_paths = constraints.get("paths")
    if not isinstance(raw_paths, list) or not raw_paths or len(raw_paths) > 32:
        raise SemanticCapabilityError("SEMANTIC_REPOSITORY_PATHS_INVALID")

    paths: list[str] = []
    for item in raw_paths:
        path = str(item or "").strip().replace("\\", "/")
        parts = path.split("/")
        if (
            not path
            or path.startswith("/")
            or path.endswith("/")
            or ".." in parts
            or "." in parts
            or any(not part for part in parts)
            or len(path) > 240
        ):
            raise SemanticCapabilityError("SEMANTIC_REPOSITORY_PATH_INVALID")
        paths.append(path)

    raw_terms = constraints.get("search_terms")
    if (
        not isinstance(raw_terms, list)
        or not raw_terms
        or len(raw_terms) > 64
    ):
        raise SemanticCapabilityError("SEMANTIC_SEARCH_TERMS_INVALID")

    search_terms: list[str] = []
    for item in raw_terms:
        term = str(item or "").strip()
        if not term or len(term) > 120:
            raise SemanticCapabilityError("SEMANTIC_SEARCH_TERM_INVALID")
        search_terms.append(term)

    max_results = constraints.get("max_results", 50)
    if (
        isinstance(max_results, bool)
        or not isinstance(max_results, int)
        or max_results < 1
        or max_results > 100
    ):
        raise SemanticCapabilityError("SEMANTIC_MAX_RESULTS_INVALID")

    bounded_context = str(request.get("bounded_context") or "").strip().upper()
    return {
        "actions": [],
        "checks": [
            {"type": "git_diff_check"},
            {
                "type": "repository_contract_audit",
                "request": {
                    "paths": paths,
                    "search_terms": search_terms,
                    "max_results": max_results,
                },
            },
        ],
        "scheduling": {
            "project_id": "EDARSAHUB",
            "bounded_context": bounded_context,
            "priority_class": "NORMAL",
            "fairness_weight": 1,
            "max_parallelism": 1,
            "resource_claims": [
                "repository_read:" + path for path in paths
            ],
            "conflict_domains": [bounded_context],
        },
    }


register_capability(
    SemanticCapability(
        code="READ_ONLY_CANARY",
        modes=("READ_ONLY",),
        builder=_read_only_canary_builder,
    )
)

register_capability(
    SemanticCapability(
        code="REPOSITORY_CONTRACT_AUDIT",
        modes=("READ_ONLY",),
        builder=_repository_contract_audit_builder,
    )
)

