def test_repository_contract_audit_expands_to_existing_readonly_check():
    job = service.build_semantic_job(
        _objective(
            capability="REPOSITORY_CONTRACT_AUDIT",
            constraints={
                "paths": [
                    "backend/modules/worker_ingress",
                    "tools/mirror_sync",
                ],
                "search_terms": [
                    "submit_objective",
                    "worker_slot_runtime",
                ],
                "max_results": 25,
            },
        ),
        current_user=_user(),
    )

    assert job["mode"] == "READ_ONLY"
    assert job["actions"] == []
    assert job["checks"][0] == {"type": "git_diff_check"}
    assert job["checks"][1] == {
        "type": "repository_contract_audit",
        "request": {
            "paths": [
                "backend/modules/worker_ingress",
                "tools/mirror_sync",
            ],
            "search_terms": [
                "submit_objective",
                "worker_slot_runtime",
            ],
            "max_results": 25,
        },
    }
    assert job["production_allowed"] is False
    assert job["scheduling"]["bounded_context"] == "WORKER_INGRESS"


